// Filtrar por horario y calcular límite según fase del día
const numbers = $input.all().map(i => i.json);

// Zona horaria Argentina
const now = new Date();
const argStr = now.toLocaleString('en-US', { timeZone: 'America/Argentina/Buenos_Aires' });
const argDate = new Date(argStr);
const hour = argDate.getHours();

// Solo entre 9AM y 22PM
if (hour < 9 || hour >= 22) {
  return [{ json: { skip: true, reason: `Fuera de horario: ${hour}hs` } }];
}

const results = [];

for (const num of numbers) {
  if (!num.phone_number || !num.instance_name) continue;

  const day = num.current_day || 1;

  // Calcular límite diario y delay según fase
  let dailyLimit, delayMinSec, delayMaxSec;
  if (day <= 3) {
    dailyLimit  = 10;
    delayMinSec = 180; // 3 min
    delayMaxSec = 480; // 8 min
  } else if (day <= 7) {
    dailyLimit  = 20;
    delayMinSec = 120; // 2 min
    delayMaxSec = 360; // 6 min
  } else if (day <= 14) {
    dailyLimit  = 50;
    delayMinSec = 60;  // 1 min
    delayMaxSec = 240; // 4 min
  } else {
    dailyLimit  = 100;
    delayMinSec = 30;  // 30 seg
    delayMaxSec = 180; // 3 min
  }

  const sentToday = num.messages_sent_today || 0;
  const remaining = dailyLimit - sentToday;

  if (remaining <= 0) continue; // ya llegó al límite de hoy

  // Calcular delay aleatorio con jitter
  const delaySec = Math.floor(Math.random() * (delayMaxSec - delayMinSec + 1)) + delayMinSec;
  const jitter = Math.floor(Math.random() * 30) - 15; // ±15 seg

  results.push({
    json: {
      ...num,
      daily_limit: dailyLimit,
      delay_sec: Math.max(10, delaySec + jitter),
      remaining_today: remaining,
      warmup_phase: day <= 3 ? 'fase1' : day <= 7 ? 'fase2' : day <= 14 ? 'fase3' : 'fase4',
      current_hour: hour
    }
  });
}

return results.length > 0 ? results : [{ json: { skip: true, reason: 'Sin números disponibles' } }];

// Elegir contacto random y mensaje según fase
const warmupNum = $('Code – Filter & Calculate Phase').item.json;
const contacts  = $input.all().map(i => i.json);

if (!contacts.length) {
  return [{ json: { skip: true, reason: 'Sin contactos de calentamiento' } }];
}

// Elegir contacto random (el menos usado)
const contact = contacts[Math.floor(Math.random() * Math.min(5, contacts.length))];

// Banco de mensajes por fase
const messages = {
  fase1: [
    'Hola! cómo andás?', 'Buenas! todo bien?', 'Ey! qué tal?',
    'Hola, cómo estás?', 'Buenas! qué hacés?', 'Hola! cómo va todo?',
    'Ey, qué onda?', 'Hola, todo bien por allá?', 'Buenas! cómo te va?',
    'Hola! cómo va el día?'
  ],
  fase2: [
    'Hola! cómo andás? 😊', 'Buenas! todo bien? 👋', 'Ey qué tal! 🙌',
    'Hola, cómo estás? 😄', 'Buenas! qué hacés? ☀️', 'Hola! cómo va todo? 👍',
    'Qué onda! todo bien? 🎉', 'Hola por acá! cómo te va? 😁',
    'Buenas! se viene el finde 🙌', 'Ey! apareció el sol por allá? ☀️',
    'Hola! tomando unos mates ☕ y vos?', 'Qué tal el día hoy? 😊',
    'Buenas! qué está pasando por allá? 👀', 'Hola! cómo está la familia? 🏠',
    'Ey! hace rato no hablamos, cómo andás? 😊'
  ],
  fase3: [
    'Hola! cómo andás? 😊 Hoy está haciendo un calor terrible por acá',
    'Buenas! todo bien? 👋 Recién salí del trabajo, qué tal el día?',
    'Ey qué tal! 🙌 Che, tenés alguna serie para recomendar?',
    'Hola! 😄 Estoy tomando unos mates, nada mejor para la tarde',
    'Buenas! ☀️ Qué semana larga, ya tengo ganas del finde',
    'Hola! 👍 Pasé por el centro hoy y estaba lleno de gente, un caos',
    'Qué onda! 🎉 Viste el partido de anoche? qué partidazo',
    'Hola! 😁 El fin de semana estuve en el campo, una paz total',
    'Buenas! 🙌 Me anoté al gimnasio otra vez, a ver si me mantengo jaja',
    'Ey! ☀️ Hoy hice compras y no podía creer los precios, todo carísimo'
  ],
  fase4: [
    'Hola! cómo andás? 😊 Hoy está haciendo un calor terrible por acá, qué tal el clima donde estás?',
    'Buenas! 👋 Recién salí del trabajo y vine caminando, qué semana larga',
    'Ey! 🙌 Che, ¿viste el partido de anoche? qué partidazo, no esperaba ese resultado',
    'Hola! 😄 Estoy tomando unos mates con galletitas, lo más. Vos qué hacés?',
    'Buenas tardes! ☀️ Se viene el finde, algún plan? Nosotros vamos al campo',
    'Hola! 👍 Pasé por el centro y estaba todo cortado, tardé el doble. Cómo te fue a vos?',
    'Qué onda! 🎉 Me enteré que abrieron una pizzería nueva acá cerca, hay que ir',
    'Hola! 😁 El fin de semana hice asado, quedó buenísimo. Vos qué hiciste?'
  ]
};

const phase = warmupNum.warmup_phase || 'fase1';
const phaseMessages = messages[phase] || messages.fase1;
const text = phaseMessages[Math.floor(Math.random() * phaseMessages.length)];

return [{
  json: {
    ...warmupNum,
    recipient_phone: contact.phone_number,
    contact_id: contact.id,
    message_text: text,
    message_type: phase === 'fase1' ? 'text' : 'emoji',
    sent_at: new Date().toISOString()
  }
}];

