// Detectar si el error es ban/403 o error genérico
const response = $input.first().json;
const responseBody = JSON.stringify(response).toLowerCase();
const statusCode = response.statusCode || 0;

const isBanned = statusCode === 403
  || responseBody.includes('banned')
  || responseBody.includes('blocked')
  || responseBody.includes('unauthorized');

const warmupData = $('Code – Pick Message & Contact').item.json;

return [{
  json: {
    ...warmupData,
    error_status: statusCode,
    error_body: JSON.stringify(response).substring(0, 200),
    new_warmup_status: isBanned ? 'banned' : 'active',
    is_banned: isBanned
  }
}];
